      "support_multi_bed_types": "std::find(bed_temp_keys.begin(), bed_temp_keys.end(), bed_temp_1st_layer_key) == bed_temp_keys.end() || is_BBL_printer || printer_cfg.opt_bool(\"support_multi_bed_types\")",
